// `migrations/ownership.rs::OS_LAYOUT_PREFIXES`, the actual root cause (a reference-scanner ownership gap,
// unrelated to T2), fixed there.
//
// AR88-C10B: on a genuinely FIRST install this is onboarding's own ungoverned-but-first write (`FloorIdentity`
// mints this checkout's identity right here). On a `--force` KERNEL REINSTALL of an ALREADY-onboarded project
// AT THE SAME PATH (`already_installed`, captured above before `install_kernel` could create `framework.lock`,
// AND this checkout's own `FloorIdentity` anchor is still there for it -- `crate::paths::
// has_local_adoption_anchor`), the authoritative floor is left exactly as it stood: `--force` reinstalls the
// kernel, it does not re-run onboarding's adoption decision outside the governed `reclassify_adoption_floor`
// route. Measured (AR88-C10B): without SOME such guard, `mv src elsewhere && gov init --force` on an
// unmoved checkout produced an authenticated, forward-sequenced, freshly sealed floor with NO CIT, NO Human
// Gate and NO owner -- an authenticated transition that was never an AUTHORISED one (OD-P2-08 §2). The anchor
// check below does not reopen that: `mv src elsewhere` changes this repository's CONTENT, never its
// canonical PATH, so `has_local_adoption_anchor` still finds this checkout's own existing entry and the
// extended condition stays false, exactly as before.
//
// **P2-AR-0096 (P2-HO-0060 §2), extending the condition.** `already_installed` alone no longer decides this:
// a RELOCATED checkout also has `framework.lock` (copied along with everything else) but no local
// `FloorIdentity` anchor for its NEW canonical path (the anchor lives outside the project, keyed by path --
// see `FloorIdentity`'s own doc -- and a plain `mv`/`git mv` of the whole project does not move it). Deleting
// `gov floor-reanchor` removed the only way back for that checkout; the replacement is to let it re-run this
// SAME onboarding decision, under the SAME `install_kernel` authority this branch already requires -- no new
// authority, no new command. `reonboarding` names exactly that case: `already_installed` (so this is not a
// brand-new project) but no anchor of its own (so `!already_installed`'s ordinary first-write branch would
// never have fired for it either).
let reonboarding = already_installed && !crate::paths::has_local_adoption_anchor(root);
let mut adoption_floor_reonboarding = Value::Null;
if !already_installed || reonboarding {
    let floor = if reonboarding {
        // P2-HO-0060 §3: strengthen the fresh derivation with the conservative, additive union of every rule
        // this MACHINE has ever authenticated for ANY checkout (protected machine state, never the project
        // document -- OD-P2-08 §2, `RESEARCH/P2-HISTORICAL-RULE-SOURCE.md`), so an attacker cannot defeat
        // re-onboarding by reshaping the tree before the operator runs it. Never applied to a genuinely first
        // install (see `union_last_known_rules_across_store`'s own doc for why).
        let unioned = crate::paths::union_last_known_rules_across_store(&adoption_floor);
        let fresh_patterns: std::collections::BTreeSet<&str> = adoption_floor
            .iter()
            .filter_map(|r| r.get("pattern").and_then(|v| v.as_str()))
            .collect();
        let restored_rules: Vec<Value> = unioned
            .iter()
            .filter(|r| {
                r.get("pattern")
                    .and_then(|v| v.as_str())
                    .map(|p| !fresh_patterns.contains(p))
                    .unwrap_or(false)
            })
            .cloned()
            .collect();
        let restored: Vec<String> = restored_rules
            .iter()
            .filter_map(|r| r.get("pattern").and_then(|v| v.as_str()).map(str::to_string))
            .collect();
        // The CONTRACT (`REPOSITORY_CONTRACT.yaml`) and the FLOOR must stay in agreement: `PolicySet::load`
        // unions the floor's own rules into the kernel template before comparing against the overlay's own
        // `paths` (`policy.rs`'s `paths_kernel` vs `paths_new`); a pattern the floor restores but the overlay
        // never declares reads as "a kernel-mandated pattern is missing from the overlay" -- a NEW, spurious
        // D027 refusal the union must not itself introduce. Splice the same restored rules into the contract.
        if !restored_rules.is_empty() {
            if let Some(arr) = contract["paths"].as_array_mut() {
                let mut merged = restored_rules.clone();
                merged.extend(arr.clone());
                *arr = merged;
            }
        }
        // OC-P2-04 §4 / P2-HO-0060 §3: disclosed regardless of whether anything was actually restored, so a
        // re-onboarding that restores NOTHING is still visibly distinguishable from an ordinary first install.
        adoption_floor_reonboarding = json!({
            "event": "PROJECT_ADOPTION_FLOOR_REONBOARDED",
            "reason": "this checkout already has a kernel installation (framework.lock) but no authenticated \
                       floor anchor for its current path -- a relocation, or a repeat onboarding with no \
                       local ledger; the floor was re-derived from this repository's own current native \
                       layout, strengthened by the machine's own protected record of every rule any checkout \
                       here has last seen authenticated, and re-authenticated under a FRESH identity (P2-HO-\
                       0060). The previous path's machine-store entry, if any, is left untouched and inert.",
            "restored_from_protected_machine_state": restored,
        });
        unioned
    } else {
        adoption_floor.clone()
    };
    crate::paths::write_project_adoption_floor(root, &floor, "init", None)?;
}
let overlay = write_overlay(root, &gov.join("kernel"), &opts, Some(contract))?;
ensure_roots(root)?;
let mut p = Project::open(root);
p.invalidate();
crate::authority::require(&p, "install_kernel").inspect_err(|_e| {
    let _ = std::fs::remove_file(gov.join("framework.lock"));
})?;
// Transaction step (9): the protected floors advance now — after the atomic commit, the verification of the
// committed bytes (`install_kernel`) and the authority check against the installed constitution, and BEFORE the
// conformance suite (IP-WS02-14). The conformance run and doctor below then describe the machine as it will
// stay, so a governance-suite record they write is not made stale by the install's own bookkeeping, and the
// health scheduler may count this machine's installed/verified records among its machine-trust inputs.
let floors = crate::srr::record_installed(&auth)?;
if let Some(intent) = &opts.intent {
    let store = crate::records::RecordStore::load(root);
    if store.of_type("project").is_empty() {
        let rec = crate::records::new_record(
            "project",
            "PRJ-0001",
            &opts.project_name,
            json!({"mission": intent, "product_intent": intent, "outcomes": [], "actors": [], "state_class": "AUTHORITATIVE"}),
        );
        crate::records::save_record(root, &rec)?;
